INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('67ad3e6c-7f80-4e36-ac09-23d5aba5b839','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"691268b0-dc99-4744-9f57-b4f424f3c3b9\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"b5d44036-7d4b-43df-99cd-9135fd9de9da\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"c769f413-7a2f-4b19-98c3-13c44416653b\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"b5d44036-7d4b-43df-99cd-9135fd9de9da\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"bdf129cc-db04-4168-8053-60ac4c58e3f3\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"9cac9e6d-f98f-41db-b072-cba31ac93461\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"bdf129cc-db04-4168-8053-60ac4c58e3f3\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"9506efca-0b0d-4bfe-a3b7-44fb26d82f63\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"bcba3935-5936-4c69-ad84-fbc2ae6a56b3\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"892fa157-ce2e-40b5-9e65-b2ba3a7603ea\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"bcba3935-5936-4c69-ad84-fbc2ae6a56b3\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"48807dd8-37df-466b-9e01-0f128a332269\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"6bf76a88-8708-484c-9a24-e2675e15dee5\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"7f5a7f47-85fb-4410-b288-dcb47a1949db\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"6bf76a88-8708-484c-9a24-e2675e15dee5\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"1fdbf38d-7c43-4d53-b2df-173d02288fa8\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"4aba2348-d4c8-4729-a157-e4d20ab55bde\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"95e55e7e-c3aa-4e20-87af-990203256a48\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"d68c51ba-2be4-4766-8186-d4cdb592fe93\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"95e55e7e-c3aa-4e20-87af-990203256a48\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"47686df0-ca09-4eba-b16d-7e6b2c139380\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"e5398bab-0403-4379-aa95-f53dd372febd\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"f9f4d9c4-aa66-4f1c-b839-b1c8518a7f21\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"e5398bab-0403-4379-aa95-f53dd372febd\",\"triggerValues\":[\"no\"]}},{\"id\":\"6ffb93d6-e805-4edf-ac88-d74e01fce4a5\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"8a8a6efb-10f2-4ecc-887e-cf3642600197\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"e864f58b-7091-4e7f-bdbc-a2e8a98eed53\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"a31f069c-bf76-46d1-a202-1aaaa1124d44\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"0abf0201-537c-4398-9843-1fb97ee41466\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"e864f58b-7091-4e7f-bdbc-a2e8a98eed53\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"4dfd0958-8440-4f6d-bccd-7f815699f7c4\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"70a98ca8-1ff3-4e84-aeb1-fbe831c3650b\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"5b6d0232-bb5f-483b-bc07-3669b4ceb2db\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"70a98ca8-1ff3-4e84-aeb1-fbe831c3650b\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"a0d4be46-67c0-42f5-a1fe-86fb2a21b63f\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"75923b0b-d381-41e0-b8e5-6e67b5eae17b\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"a0d4be46-67c0-42f5-a1fe-86fb2a21b63f\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"d9d86a0e-1f2d-4832-9d58-a3389e81f72b\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"cba20f61-2459-421e-a582-5f15fe84ae96\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"8c87e24e-394b-48d2-bf3c-6af4aff46d4f\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"97b62c27-8f90-41db-ad27-4f9a3ed6ba5e\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"8c87e24e-394b-48d2-bf3c-6af4aff46d4f\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"597391cd-09af-4f1a-9d64-e0e588216d0c\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T10:45:28.452Z','2026-10-21T10:45:28.452Z','usine'),
('b404d3f2-1245-4917-80ea-2fbdd0f39c42','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"5d0ab2f8-6ec1-44dc-90be-28a3ea94d263\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"88f0ab39-c4dc-4534-b0a7-7d13ed0c6cd1\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"0570bd8f-17b5-4a09-beb8-39b6f7b9e843\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"88f0ab39-c4dc-4534-b0a7-7d13ed0c6cd1\",\"triggerValues\":[\"no\"]}},{\"id\":\"38429f2c-0db3-4584-ad50-ca00e7e44c52\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"3419480a-b0ac-426a-b3d6-25611f245223\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"38429f2c-0db3-4584-ad50-ca00e7e44c52\",\"triggerValues\":[\"no\"]}},{\"id\":\"488c6d24-6c1d-40f2-9647-4cee3b091a0e\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"7bcd23c3-1a6d-4ef2-b8cb-62ac38e4c6ef\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"488c6d24-6c1d-40f2-9647-4cee3b091a0e\",\"triggerValues\":[\"no\"]}},{\"id\":\"c37b8705-f77d-4ebd-a410-bebf16df2a1f\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"91674db8-1648-433f-b290-cc679c1f2af5\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"c37b8705-f77d-4ebd-a410-bebf16df2a1f\",\"triggerValues\":[\"no\"]}},{\"id\":\"a6262e7b-696d-43d0-b3d9-fe4acc313766\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"7f1bf095-6157-43f4-95a5-1bb743cd6c3e\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"39fc94f3-943e-4eae-9306-7894592811d3\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"7f1bf095-6157-43f4-95a5-1bb743cd6c3e\",\"triggerValues\":[\"no\"]}},{\"id\":\"f42145b2-54a2-4e84-8a48-b277c345f7c4\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"2ba14f83-3179-4e0d-b69a-d7127d5d9a27\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"5a93a679-bdc4-4f97-bfcc-e186b22ef503\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"7f27e9af-d384-4db5-b6ef-3051968962a4\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"5a93a679-bdc4-4f97-bfcc-e186b22ef503\",\"triggerValues\":[\"no\"]}},{\"id\":\"4f34784d-d11b-4167-b901-daa2450bf7d9\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"ce73efd0-686c-4b64-9d1b-3de93c18309a\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"4f34784d-d11b-4167-b901-daa2450bf7d9\",\"triggerValues\":[\"no\"]}},{\"id\":\"7f0a3f41-1321-4a9d-9226-e0934f994162\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"2a34dc9b-0e30-4886-8c25-d5efb4969b0d\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"7f0a3f41-1321-4a9d-9226-e0934f994162\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"00e6820a-e097-44e5-b9ef-3f97393e3bb1\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"a75f9e00-b419-4767-8dc9-ebe237bcfdf7\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"39c8250c-ae65-434b-99d6-db70c60110a2\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a75f9e00-b419-4767-8dc9-ebe237bcfdf7\",\"triggerValues\":[\"no\"]}},{\"id\":\"cd56ebfc-31c8-4dc6-9ca0-748637e801f1\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"a75f9e00-b419-4767-8dc9-ebe237bcfdf7\",\"triggerValues\":[\"no\"]}},{\"id\":\"6dbae7c1-553a-4e54-afd8-c60eecdcc051\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"cfc06412-1ad6-4edb-996b-46d9a3c8ed04\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"6dbae7c1-553a-4e54-afd8-c60eecdcc051\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"2ad9c9fa-5d8c-4e77-9fdb-f356aeb8ee8d\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"82bda14b-4626-403b-adfd-cea94d70690f\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"5efa28f9-f5cf-4a2e-ab88-c0c34415346e\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"82bda14b-4626-403b-adfd-cea94d70690f\",\"triggerValues\":[\"yes\"]}},{\"id\":\"4811b1be-8cd2-4164-8992-76f1428dd75e\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"82bda14b-4626-403b-adfd-cea94d70690f\",\"triggerValues\":[\"yes\"]}},{\"id\":\"45558f11-8286-491c-8578-207553ea0046\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"82bda14b-4626-403b-adfd-cea94d70690f\",\"triggerValues\":[\"yes\"]}},{\"id\":\"522ac090-0045-40a0-a2be-342e19de214c\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"82bda14b-4626-403b-adfd-cea94d70690f\",\"triggerValues\":[\"yes\"]}}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T10:45:28.457Z','2026-10-21T10:45:28.457Z','container'),
('c3ea84a5-c447-4004-975c-80c8e530fedd','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"7b085f7c-78b2-4874-b8ce-f71f66d4cdc9\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"1bcd4151-b1c6-4296-ba0f-35977af290cb\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"edd0d575-3f3c-4b98-b686-c87f179bec72\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"1bcd4151-b1c6-4296-ba0f-35977af290cb\",\"triggerValues\":[\"no\"]}},{\"id\":\"0cee342c-7048-4a1f-9334-a45e0c40b15e\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"22b0570b-5657-404c-baaa-46c9bcc5e531\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0cee342c-7048-4a1f-9334-a45e0c40b15e\",\"triggerValues\":[\"yes\"]}},{\"id\":\"ccf0eaf8-3add-4058-aaf1-fae8cca76f5b\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"758f7393-4589-4449-a8a5-071a3fb13364\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"ccf0eaf8-3add-4058-aaf1-fae8cca76f5b\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"a2d5915f-70c2-41db-8323-c7a03f6e7919\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"74ad72ab-1acf-4131-ad59-6eee5551d54b\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"64f0bc01-1484-4ea3-9d2d-ab2df59270b1\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"74ad72ab-1acf-4131-ad59-6eee5551d54b\",\"triggerValues\":[\"yes\"]}},{\"id\":\"efec8098-0587-4531-890b-f68d20546a31\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"74ad72ab-1acf-4131-ad59-6eee5551d54b\",\"triggerValues\":[\"yes\"]}},{\"id\":\"28d64677-2df7-4786-a5a2-a6f462d82d2f\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"74ad72ab-1acf-4131-ad59-6eee5551d54b\",\"triggerValues\":[\"yes\"]}},{\"id\":\"db201bfd-65a3-4096-99a9-7ac246126486\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"6ec1ca69-9eeb-4668-8bb7-31df94347adc\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"db201bfd-65a3-4096-99a9-7ac246126486\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"257695e2-8576-48c2-9d4d-6a200ab9eafb\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"16bb4147-b6b3-4ab5-8c39-8f078d527608\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"afc8d9de-b2a1-4e09-aef4-cf473fb327ad\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"16bb4147-b6b3-4ab5-8c39-8f078d527608\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"a784228b-9105-4811-9062-f708f37feb3e\",\"text\":\"Les remises accordées sont-elles validées officiellement avant application ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"873b64f8-c545-4251-a2ea-140830063373\",\"text\":\"Les retours clients sont-ils traités selon la procédure (déclaration, validation direction) ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"effae06e-2c04-4bc5-89a5-b44bf32ef7be\",\"text\":\"Précisez les retours en attente et l\'origine du blocage\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"873b64f8-c545-4251-a2ea-140830063373\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"1083b720-136d-4569-8ec4-748144c9229f\",\"label\":\"Organisation et ressources humaines\",\"questions\":[{\"id\":\"fe5ae55b-4151-4e6a-8aa6-92adbdd1fe97\",\"text\":\"Les effectifs administratifs sont-ils suffisants pour les tâches du dépôt ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"bc08d8a3-450f-402b-8d68-5af6aaf5c19f\",\"text\":\"Précisez les tâches impactées et les recommandations (recrutement, réorganisation…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"fe5ae55b-4151-4e6a-8aa6-92adbdd1fe97\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"3bb94785-9adc-4899-a209-1b54be5baf93\",\"text\":\"Un organigramme clair et une répartition des tâches sont-ils en place ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true}]},{\"id\":\"3f62d540-679b-4c4b-b60f-985ca4cfd153\",\"label\":\"Suivi balance client, recouvrement et effets\",\"questions\":[{\"id\":\"b9c16b2e-0c71-41da-8cc1-e2e248a5d940\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"cf51c23c-34f0-440b-b594-61e512a47762\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"a90d71e6-f9fb-4e8b-b7dd-21606f392319\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"b9c16b2e-0c71-41da-8cc1-e2e248a5d940\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"fd4c9d54-a5b8-42f1-9af7-1c4adfef17c2\",\"text\":\"La gestion des effets (traites, échéances) est-elle rigoureuse et à jour ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T10:45:28.455Z','2026-10-21T10:45:28.455Z','depot');
